package main

// BC7 (BPTC) block decoder. Layout and tables from the Khronos specification
// ARB_texture_compression_bptc (Table.P2, Table.P3, Table.A2, Table.A3a,
// Table.A3b).

import "image/color"

type bc7Mode struct{ ns, pb, rb, isb, cb, ab, epb, spb, ib, ib2 int }

var bc7Modes = [8]bc7Mode{
	{3, 4, 0, 0, 4, 0, 1, 0, 3, 0},
	{2, 6, 0, 0, 6, 0, 0, 1, 3, 0},
	{3, 6, 0, 0, 5, 0, 0, 0, 2, 0},
	{2, 6, 0, 0, 7, 0, 1, 0, 2, 0},
	{1, 0, 2, 1, 5, 6, 0, 0, 2, 3},
	{1, 0, 2, 0, 7, 8, 0, 0, 2, 2},
	{1, 0, 0, 0, 7, 7, 1, 0, 4, 0},
	{2, 6, 0, 0, 5, 5, 1, 0, 2, 0},
}

// Subset of each of the 16 pixels, 64 partitions, one digit per pixel.
const bc7P2 = ""

const bc7P3 = ""

// Anchor pixel of the second subset (two subsets), and of the second and third subsets (three subsets), per partition.
var bc7A2 = [64]int{15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 2, 8, 2, 2, 8, 8, 15, 2, 8, 2, 2, 8, 8, 2, 2,
	15, 15, 6, 8, 2, 8, 15, 15, 2, 8, 2, 2, 2, 15, 15, 6, 6, 2, 6, 8, 15, 15, 2, 2, 15, 15, 15, 15, 15, 2, 2, 15}

var bc7A3a = [64]int{3, 3, 15, 15, 8, 3, 15, 15, 8, 8, 6, 6, 6, 5, 3, 3, 3, 3, 8, 15, 3, 3, 6, 10, 5, 8, 8, 6, 8, 5, 15, 15,
	8, 15, 3, 5, 6, 10, 8, 15, 15, 3, 15, 5, 15, 15, 15, 15, 3, 15, 5, 5, 5, 8, 5, 10, 5, 10, 8, 13, 15, 12, 3, 3}

var bc7A3b = [64]int{15, 8, 8, 3, 15, 15, 3, 8, 15, 15, 15, 15, 15, 15, 15, 8, 15, 8, 15, 3, 15, 8, 15, 8, 3, 15, 6, 10, 15, 15, 10, 8,
	15, 3, 15, 10, 10, 8, 9, 10, 6, 15, 8, 15, 3, 6, 6, 8, 15, 3, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 3, 15, 15, 8}

var bc7Weights = map[int][]int{
	2: {0, 21, 43, 64},
	3: {0, 9, 18, 27, 37, 46, 55, 64},
	4: {0, 4, 9, 13, 17, 21, 26, 30, 34, 38, 43, 47, 51, 55, 60, 64},
}

type bitReader struct {
	b   []byte
	pos int
}

func (r *bitReader) read(n int) int {
	v := 0
	for i := 0; i < n; i++ {
		v |= int(r.b[r.pos>>3]>>(uint(r.pos)&7)&1) << uint(i)
		r.pos++
	}
	return v
}

// decodeBC7Block decodes one 16-byte block into 16 pixels, row by row.
func decodeBC7Block(blk []byte) (px [16]color.NRGBA) {
	r := &bitReader{b: blk}
	mode := 0
	for mode < 8 && r.read(1) == 0 {
		mode++
	}
	if mode == 8 {
		return px // reserved: transparent black
	}
	m := bc7Modes[mode]
	part, rot, sel := r.read(m.pb), r.read(m.rb), r.read(m.isb)
	n := m.ns * 2
	var ep [6][4]int
	for c := 0; c < 3; c++ {
		for e := 0; e < n; e++ {
			ep[e][c] = r.read(m.cb)
		}
	}
	for e := 0; e < n; e++ {
		if m.ab > 0 {
			ep[e][3] = r.read(m.ab)
		}
	}
	cbits, abits := m.cb, m.ab
	if m.epb == 1 || m.spb == 1 {
		var pbit [6]int
		if m.epb == 1 { // one per endpoint
			for e := 0; e < n; e++ {
				pbit[e] = r.read(1)
			}
		} else { // one per subset, shared by its two endpoints
			for s := 0; s < m.ns; s++ {
				p := r.read(1)
				pbit[s*2], pbit[s*2+1] = p, p
			}
		}
		for e := 0; e < n; e++ {
			for c := 0; c < 3; c++ {
				ep[e][c] = ep[e][c]<<1 | pbit[e]
			}
			if m.ab > 0 {
				ep[e][3] = ep[e][3]<<1 | pbit[e]
			}
		}
		cbits++
		if m.ab > 0 {
			abits++
		}
	}
	expand := func(v, bits int) int {
		v <<= uint(8 - bits)
		return v | v>>uint(bits)
	}
	for e := 0; e < n; e++ {
		for c := 0; c < 3; c++ {
			ep[e][c] = expand(ep[e][c], cbits)
		}
		if m.ab > 0 {
			ep[e][3] = expand(ep[e][3], abits)
		} else {
			ep[e][3] = 255
		}
	}
	subset := func(i int) int {
		switch m.ns {
		case 2:
			return int(bc7P2[part*16+i] - '0')
		case 3:
			return int(bc7P3[part*16+i] - '0')
		}
		return 0
	}
	anchor := func(i int) bool {
		if i == 0 {
			return true
		}
		switch m.ns {
		case 2:
			return i == bc7A2[part]
		case 3:
			return i == bc7A3a[part] || i == bc7A3b[part]
		}
		return false
	}
	var idx1, idx2 [16]int
	for i := 0; i < 16; i++ {
		bits := m.ib
		if anchor(i) {
			bits--
		}
		idx1[i] = r.read(bits)
	}
	if m.ib2 > 0 {
		for i := 0; i < 16; i++ {
			bits := m.ib2
			if i == 0 {
				bits--
			}
			idx2[i] = r.read(bits)
		}
	}
	lerp := func(a, b, w int) int { return ((64-w)*a + w*b + 32) >> 6 }
	for i := 0; i < 16; i++ {
		s := subset(i)
		e0, e1 := ep[s*2], ep[s*2+1]
		cw, aw := bc7Weights[m.ib][idx1[i]], bc7Weights[m.ib][idx1[i]]
		if m.ib2 > 0 {
			if sel == 0 {
				aw = bc7Weights[m.ib2][idx2[i]]
			} else {
				cw, aw = bc7Weights[m.ib2][idx2[i]], bc7Weights[m.ib][idx1[i]]
			}
		}
		v := [4]int{lerp(e0[0], e1[0], cw), lerp(e0[1], e1[1], cw), lerp(e0[2], e1[2], cw), lerp(e0[3], e1[3], aw)}
		switch rot {
		case 1:
			v[3], v[0] = v[0], v[3]
		case 2:
			v[3], v[1] = v[1], v[3]
		case 3:
			v[3], v[2] = v[2], v[3]
		}
		px[i] = color.NRGBA{uint8(v[0]), uint8(v[1]), uint8(v[2]), uint8(v[3])}
	}
	return px
}
